SELECT DATE(event_time) AS day, COUNT(DISTINCT user_id) AS active_users
FROM events
GROUP BY day;

SELECT u.name
FROM users u
WHERE NOT EXISTS (SELECT 1 FROM events e WHERE e.user_id = u.id);

SELECT id, user_id,
       ROUND((JULIANDAY(event_time) - JULIANDAY(LAG(event_time) OVER (PARTITION BY user_id ORDER BY event_time, id))) * 24 * 60, 2) AS minutes_since_prev
FROM events;

WITH daily AS (
  SELECT DATE(event_time) AS day, COUNT(*) AS n FROM events GROUP BY day
)
SELECT day,
       SUM(n) OVER (ORDER BY JULIANDAY(day) RANGE BETWEEN 6 PRECEDING AND CURRENT ROW) AS events_7d
FROM daily;

WITH per_user AS (
  SELECT user_id, COUNT(*) AS n FROM events GROUP BY user_id
)
SELECT AVG(n) AS median_events FROM (
  SELECT n FROM per_user
  ORDER BY n
  LIMIT 2 - (SELECT COUNT(*) FROM per_user) % 2
  OFFSET (SELECT (COUNT(*) - 1) / 2 FROM per_user)
);
